SELECT /* getMenuDtl */

  FROM TM_ADMENU
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}



  SELECT /* getSubMenuList */

    FROM TM_ADMENU
   WHERE MENU_NUMB = #{menuNumb}
     AND SUBX_NUMB != #{topMenuSubxNumb}
ORDER BY NVL(SORT_ORDR, 9999) DESC

mapper.insert:
/* setMenu */
INSERT INTO TM_ADMENU (
            MENU_NUMB
          , SUBX_NUMB
          , MENU_NAME
          , MENU_URLX
          , SORT_ORDR
          , USEE_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{menuNumb}
          , #{subxNumb}
          , #{menuName}
          , #{menuUrlx}
          , #{sortOrdr,jdbcType=NUMERIC}
          , #{useeYsno}
          , #{regiAdmn}
          , SYSTIMESTAMP
          , #{updtAdmn}
          , SYSTIMESTAMP
)


/* setMenuAuth */
INSERT INTO TB_AUTHMN (
            AUTH_CODE
          , MENU_NUMB
          , SUBX_NUMB
          , READ_YSNO
          , WRIT_YSNO
          , DELT_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
)
SELECT A.AUTH_CODE
     , #{menuNumb}
     , #{subxNumb}
     , #{yes}
     , #{yes}
     , #{yes}
     , #{regiAdmn}
     , SYSTIMESTAMP
     , #{updtAdmn}
     , SYSTIMESTAMP
  FROM TM_AUTHXM A

mapper.update:
UPDATE /* uptMenu */
       TM_ADMENU
   SET MENU_NAME = #{menuName}
     , MENU_URLX = #{menuUrlx}
     , SORT_ORDR = #{sortOrdr,jdbcType=NUMERIC}
     , USEE_YSNO = #{useeYsno}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = SYSTIMESTAMP
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}

mapper.delete:
DELETE /* delMenu */
  FROM TM_ADMENU
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}

DELETE /* delMenuAuth */
  FROM TB_AUTHMN
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}
